  AND user_no = #{userNo}
  AND is_deleted = 0

mapper.update:
UPDATE ultary_pet
SET is_deleted = 1,
	deleted_at = NOW()
WHERE pet_id = #{petId}
  AND user_no = #{userNo}
  AND is_deleted = 0

